selector_to_html = {"a[href=\"AnnularDuct.html#pyskyfire.ducts.annular.AnnularDuct\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.ducts.annular.AnnularDuct\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.ducts.annular.</span></span><span class=\"sig-name descname\"><span class=\"pre\">AnnularDuct</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">mean_line</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">height</span></span></em>, <em class=\"sig-param\"><span class=\"keyword-only-separator o\"><abbr title=\"Keyword-only parameters separator (PEP 3102)\"><span class=\"pre\">*</span></abbr></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">roughness</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a><span class=\"w\"> </span><span class=\"p\"><span class=\"pre\">|</span></span><span class=\"w\"> </span><span class=\"pre\">Callable</span><span class=\"p\"><span class=\"pre\">[</span></span><span class=\"p\"><span class=\"pre\">[</span></span><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a><span class=\"p\"><span class=\"pre\">]</span></span><span class=\"p\"><span class=\"pre\">,</span></span><span class=\"w\"> </span><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a><span class=\"p\"><span class=\"pre\">]</span></span></span><span class=\"w\"> </span><span class=\"o\"><span class=\"pre\">=</span></span><span class=\"w\"> </span><span class=\"default_value\"><span class=\"pre\">0.0</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>A stationary annulus about the shaft (+x), turning in the meridional plane.</p><p>The duct is its mean line, an <code class=\"docutils literal notranslate\"><span class=\"pre\">(x,</span> <span class=\"pre\">r)</span></code> curve from inlet to outlet, and\nthe height of the passage across it. Each span line is drawn through a\nmean-line station normal to the mean line, so the frustum it sweeps round\nthe axis is the area the through-flow crosses. The walls are the span\nlines\u2019 ends. Use <a class=\"reference internal\" href=\"#pyskyfire.ducts.annular.AnnularDuct.from_walls\" title=\"pyskyfire.ducts.annular.AnnularDuct.from_walls\"><code class=\"xref py py-meth docutils literal notranslate\"><span class=\"pre\">from_walls()</span></code></a> to start from given walls instead.</p><p class=\"rubric\">Notes</p><p>The passage may not run backward along the shaft: the walls are named\nhub and shroud by radius, and a mean line heading toward -x would swap\nthem. Its walls may not fold either, so every turn\u2019s radius must exceed\nhalf the height.</p></dd>", "a[href=\"#module-pyskyfire.ducts.annular\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.ducts.annular<a class=\"headerlink\" href=\"#module-pyskyfire.ducts.annular\" title=\"Link to this heading\">\u00b6</a></h1><p>Annular ducts about the machine\u2019s shaft.</p><p><a class=\"reference internal\" href=\"AnnularDuct.html#pyskyfire.ducts.annular.AnnularDuct\" title=\"pyskyfire.ducts.annular.AnnularDuct\"><code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">AnnularDuct</span></code></a> is a passage between a hub and a shroud, both walls of\nrevolution about the shaft (+x). Its walls are curves in the meridional\n<code class=\"docutils literal notranslate\"><span class=\"pre\">(x,</span> <span class=\"pre\">r)</span></code> plane, so it can turn between axial and radial: a turbine\u2019s inlet\nor exhaust annulus, or the crossover that carries a pump stage\u2019s radial\ndischarge round to the next eye. It is built on\n<code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">MeridionalPassage</span></code>, with its span lines drawn normal\nto the mean line so the area they sweep is the flow area.</p>", "a[href=\"#classes\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Classes<a class=\"headerlink\" href=\"#classes\" title=\"Link to this heading\">\u00b6</a></h2>", "a[href=\"../pipe/index.html#module-pyskyfire.ducts.pipe\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.ducts.pipe<a class=\"headerlink\" href=\"#module-pyskyfire.ducts.pipe\" title=\"Link to this heading\">\u00b6</a></h1><p>Explicit pipe geometry construction and pressure-loss marching.</p><p>A <a class=\"reference internal\" href=\"../pipe/Pipe.html#pyskyfire.ducts.pipe.Pipe\" title=\"pyskyfire.ducts.pipe.Pipe\"><code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">Pipe</span></code></a> is a duct swept along a <code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">Path</span></code>: a circular bore,\noptionally with a concentric core inside it, such as a centrebody or the inner\nline of coaxial tubing. It contains the same <code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">PathStation</span></code> and\nconnection objects that its solver uses. <code class=\"xref py py-func docutils literal notranslate\"><span class=\"pre\">generate_path_stations()</span></code> is\nonly a convenience for turning human-friendly corner vertices into tangent\nstations and connections; users may construct the resolved objects directly.\nWhere the section varies, the pipe adds the stations its loss march needs by\nitself; see <a class=\"reference internal\" href=\"../pipe/Pipe.html#pyskyfire.ducts.pipe.Pipe\" title=\"pyskyfire.ducts.pipe.Pipe\"><code class=\"xref py py-class docutils literal notranslate\"><span class=\"pre\">Pipe</span></code></a>.</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 600, interactive: false,
                onShow(instance) {MathJax.typesetPromise([instance.popper]).then(() => {});},
            });
        };
    };
    console.log("tippy tips loaded!");
};
